    def related_objects(self, related, objs):
        """
        Get a QuerySet of objects related to `objs` via the relation `related`.
        This method is optimized to only select fields that are needed for the
        deletion operation to avoid pulling in large or binary fields that
        might cause decoding errors.
        """
        model = related.related_model
        pk_name = model._meta.pk.name
        # Always include the primary key
        fields = [pk_name]
        # Include any fields that are part of a unique_together constraint that
        # involves the foreign key field used in this relation.
        for ut in getattr(model._meta, "unique_together", []):
            # unique_together can be a tuple of tuples or a single field name.
            if isinstance(ut, (list, tuple)):
                if related.field.name in ut:
                    for field_name in ut:
                        if field_name not in fields:
                            fields.append(field_name)
            else:
                if ut == related.field.name:
                    # nothing extra needed beyond the pk
                    pass
        qs = related.related_model._base_manager.using(self.using).filter(
            **{"%s__in" % related.field.name: objs}
        ).only(*fields)
        return qs
