    fails to populate ``username`` or ``password`` due to changes in
    Python 3.8.12.  It parses the ``netloc`` manually to extract any
    authentication information.
    """
    parsed = urlparse(url)

    # If there's no netloc, we cannot have auth.
    if not parsed.netloc:
        return ('', '')

    # Extract userinfo before '@'
    if '@' not in parsed.netloc:
        return ('', '')
    userinfo, _ = parsed.netloc.rsplit('@', 1)
