def get_environ_proxies(url, no_proxy=None):
    """
    Return a dict of environment proxies.

    :rtype: dict
    """
    # If the URL should bypass proxies, return an empty mapping
    if should_bypass_proxies(url, no_proxy=no_proxy):
        return {}

    # Fetch the raw proxy configuration from the environment
    raw_proxies = getproxies()

    # Re-quote credentials in proxy URLs to preserve special characters
    processed = {}
    for scheme, proxy_url in raw_proxies.items():
        try:
            parsed = urlparse(proxy_url)
            if parsed.username or parsed.password:
                # Percent-encode username and password
                username = quote(parsed.username, safe='')
                password = quote(parsed.password, safe='')
                netloc = f"{username}:{password}@{parsed.hostname}"
                if parsed.port:
                    netloc += f":{parsed.port}"
                rebuilt = urlunparse(
                    (
                        parsed.scheme,
                        netloc,
                        parsed.path,
                        parsed.params,
                        parsed.query,
                        parsed.fragment,
                    )
                )
                processed[scheme] = rebuilt
            else:
                processed[scheme] = proxy_url
        except Exception:
            # Fallback to the original proxy URL on any error
            processed[scheme] = proxy_url

    return processed
